import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useOrder } from '../contexts/OrderContext';

const PaymentSuccess: React.FC = () => {
  const navigate = useNavigate();
  const { clearOrder } = useOrder();
  
  useEffect(() => {
    // 页面加载时清空购物车
    clearOrder();
  }, [clearOrder]);

  const handleReturnHome = () => {
    // 确保导航到首页
    navigate('/home');
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center">
      <div className="bg-white p-8 rounded-lg shadow-lg max-w-md w-full text-center">
        <div className="w-16 h-16 mx-auto mb-4 bg-green-100 rounded-full flex items-center justify-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        </div>
        <h2 className="text-2xl font-bold text-gray-800 mb-2">Order Successful!</h2>
        <p className="text-gray-600 mb-6">
          Thank you for your order. We've received your order successfully.
        </p>
        <p className="text-gray-500 mb-8">
          Your beers will be prepared and ready for pickup soon.
        </p>
        <button
          onClick={handleReturnHome}
          className="w-full py-3 bg-red-500 text-white rounded-lg hover:bg-red-600 transition-colors"
        >
          Return to Home
        </button>
      </div>
    </div>
  );
};

export default PaymentSuccess; 